# Exact forms reviewed against each full source sentence. Tokenizer proposals are
# retained separately as working provenance, never used by the runtime or build.
import json
rows=json.loads((P/'proposals.json').read_text())[:222]
overrides={12:['許されない'],24:['限らせていただきます'],27:['行われた'],31:['従わなければ'],32:['従って'],48:['築かれる'],58:['破られなかった','破った'],62:['迫られている'],64:['誘われて'],75:['緩み'],85:['謹んで'],86:['謹んで'],92:['誤れば'],110:['襲われて'],131:['煽られて'],145:['憎んで','憎まず'],198:['慕われる'],213:['弄ばれ'],218:['揉まれ']}
records=[]
for i,row in enumerate(rows):
 forms=overrides.get(i,row['proposal']);assert forms and all(f in row['sentence'] and len(f)>1 for f in forms)
 records.append({k:row[k] for k in ['kind','id','word','exampleIndex','sentence']}|dict(forms=forms))
def add(kind,id,index,form,correct,a,b,c,note):
 db=vd if kind=='v' else gd;word=next(x['w'] for x in (v if kind=='v' else g) if x['id']==id)
 sentence=db[str(id)]['examples'][index];assert form in sentence
 records.append(dict(kind=kind,id=id,word=word,exampleIndex=index,sentence=sentence,forms=[form],quiz=dict(correct=correct,wrong=[a,b,c],note=note)))
